% prio: The total priority of jobs
% pop-size: Population size
% job-num: The total number of jobs
% all-oper: The sum of operation for all jobs
% ope-set: The set of the number of operations for each job
1: Pop_st ← cell (1: pop-size, 1);
2: For j = 1 to pop-size Do
3: num ← 0; Chrom ← zeros (6, all_oer);
4: For i = 1 to job-num Do
5: oper ← ope-set (2, i); Chrom(1, num+1:num+oper) ← ones (1, oper)*i; num ← num+oper;
6: End For
7: For r = 1 to job-num Do
8: pri-set(r)=randperm (prio);
9: HA=randperm (job-num); chrom (HA)=pri-set(1:job-num);
10: Chrom (5,:) ←Randomly arrange the priority in Chrom (5,:);
11: For j = 1:all-oper Do
12: P=unidrnd (job-num+sum(1:pri-1));
13: If the number of P is bigger than the number of P Then
14: n = P-job-num; Randomly select a job with a priority less than n, named BA;
15: Chrom (4,:) ← Randomly arrange the BA in Chrom (4,:);

